import{_ as t,o as r,c as s,a6 as o}from"./chunks/framework.CCKCzdWs.js";const f=JSON.parse(`{"title":"The editor's status bar","description":"The Piwi item in the status bar of VS Code or a JetBrains IDE: the latest Playwright run of your branch or the run in progress, the config it speaks for, its menu, and when it turns red.","frontmatter":{"title":"The editor's status bar","description":"The Piwi item in the status bar of VS Code or a JetBrains IDE: the latest Playwright run of your branch or the run in progress, the config it speaks for, its menu, and when it turns red.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-status-bar.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-status-bar.html"}],["meta",{"property":"og:title","content":"The editor's status bar | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The Piwi item in the status bar of VS Code or a JetBrains IDE: the latest Playwright run of your branch or the run in progress, the config it speaks for, its menu, and when it turns red."}]]},"headers":[],"relativePath":"features/editor-status-bar.md","filePath":"features/editor-status-bar.md","lastUpdated":1794653680000}`),n={name:"features/editor-status-bar.md"};function a(i,e,h,d,l,u){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="the-editor-s-status-bar" tabindex="-1">The editor&#39;s status bar <a class="header-anchor" href="#the-editor-s-status-bar" aria-label="Permalink to &quot;The editor&#39;s status bar&quot;">​</a></h1><p>The Piwi item in the status bar of the <a href="./editors.html">editor extensions</a> says how the latest run of your branch went, or how far a run in progress is, for the Playwright config of the file you are editing.</p><p>The latest complete run on the branch: how many tests passed, failed and were flaky, or what still fails and what your local runs fixed (<code>2 failing · 1 fixed locally</code>). While a run started from this editor, or <a href="./watch-running-test.html#a-ci-run-of-your-branch">another run of the branch</a>, is in progress, the item says where its test stands stopped or the call a paused one waits in, that it is shared live, and how far it is (<code>Piwi: held at its failure · checkout.page.ts:12 · run #124 · 4 of 9 · 1 failed</code>), in the same words in both editors, and returns to the latest run when it ends. A test that waits for you marks the item until you answer it: its background turns yellow in VS Code, and its icon takes a dot in a JetBrains IDE.</p><p>With several Playwright configs, the item speaks for the config of the file you are editing, the deepest config folder that holds it, and follows you from file to file; outside every config folder, it shows the first connected config. Its tooltip names the config (<code>The active file&#39;s Playwright config, in apps/admin (one of 3)</code>), then holds the run&#39;s counts, the baseline, your local runs since, the run in progress, and when the run was read (<code>Updated 12 s ago · live</code> while the event stream is connected, <code>· read every minute</code> without it).</p><p>In VS Code, a click opens <strong>Piwi: Open the Piwi menu</strong>, in the JetBrains menu&#39;s sections, the item&#39;s own action first: Enter reads the latest run and its failures again (<strong>Refresh the latest run</strong>), without the indexes <strong>Reload Piwi</strong> fetches, or goes to the stopped line while a test is stopped. The run&#39;s controls and its share are in the menu while a run is live. When the extension is not connected, the item says why, and its first entry is <strong>Connect…</strong>, or <strong>Reload Piwi</strong> for an <a href="./editor-connection.html#an-unreachable-instance">unreachable instance</a> or a desktop app to restart.</p><p>The item turns red (its background in VS Code, its text in a JetBrains IDE) only for a test a run you started from the editor failed that the baseline does not fail, until a run fixes it or the editor restarts: a CI failure or a teammate&#39;s is counted, never red, and so is a run in progress. <code>piwi.statusBarAlert</code> in VS Code, and <strong>The status bar item&#39;s text turns red</strong> on Settings → Tools → Piwi in a JetBrains IDE, choose any failing test or never instead.</p><p>In a JetBrains IDE, an icon before the text shows the state of the run the item counts (running, failing, passed), of a recording, or of the connection. A click opens a menu of the <strong>Tools → Piwi</strong> actions that apply, led by what the item calls for: <strong>Refresh the latest run</strong>, <strong>Reload Piwi</strong> for an unreachable instance or a desktop app to restart, <strong>Connect…</strong> while not connected, <strong>Node.js settings…</strong> when Node.js is missing or too old, or <strong>Go to the recorded lines</strong> while a recording runs, with <strong>Pause recording</strong>, <strong>Resume recording</strong> and <strong>Stop recording</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-runs.html">Runs from the editor</a>: run tests from the editor and see their results.</li><li><a href="./editor-failures.html">Failures in the editor</a>: the failures a run leaves, at their lines and in the failures view.</li><li><a href="./editor-connection.html">Editor connection</a>: the instance the editor reads, and its key.</li></ul>',9)])])}const g=t(n,[["render",a]]);export{f as __pageData,g as default};
